import React, { useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import axios from 'axios';
import './RegistrationForm.css';

function RegistrationStep2() {
  const location = useLocation();
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    ...location.state.formData,
    height: '',
    heightUnit: 'cm',
    weight: '',
    weightUnit: 'kg',
    desiredWeight: '',
    sex: '',
    dob: ''
  });

  // Handle input change
  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value,
    });
  };

  // Handle form submission
  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const response = await axios.post('/api/users', formData);
      console.log('User created:', response.data);
      navigate('/login');
    } catch (error) {
      console.error('Error creating user:', error);
    }
  };

  // Handle back button click
  const handleBack = () => {
    navigate('/', { state: { formData } });
  };

  return (
    <form onSubmit={handleSubmit}>
      <h2>Step 2: Personal Details</h2>
      <div>
        <label>Height:</label>
        <div className="height-input">
          <select
            id="height-feet"
            name="heightFeet"
            value={formData.heightFeet}
            onChange={handleChange}
          >
            <option value="" disabled selected>Feet</option>
            <option value="3">3'</option>
            <option value="4">4'</option>
            <option value="5">5'</option>
            <option value="6">6'</option>
            <option value="7">7'</option>
          </select>
          <select
            id="height-inches"
            name="heightInches"
            value={formData.heightInches}
            onChange={handleChange}
          >
            <option value="" disabled selected>Inches</option>
            <option value="0">0"</option>
            <option value="1">1"</option>
            <option value="2">2"</option>
            <option value="3">3"</option>
            <option value="4">4"</option>
            <option value="5">5"</option>
            <option value="6">6"</option>
            <option value="7">7"</option>
            <option value="8">8"</option>
            <option value="9">9"</option>
            <option value="10">10"</option>
            <option value="11">11"</option>
          </select>
          <input
            type="text"
            id="height-text"
            name="heightText"
            value={formData.heightText}
            onChange={handleChange}
            placeholder="Or type (e.g., 5'8)"
            maxlength="5"
          />
        </div>
      </div>
      <div>
        <label>Weight:</label>
        <div className="input-group">
          <input
            type="text"
            name="weight"
            value={formData.weight}
            onChange={handleChange}
            placeholder="Enter your weight"
          />
          <select
            name="weightUnit"
            value={formData.weightUnit}
            onChange={handleChange}
          >
            <option value="kg">kg</option>
            <option value="lbs">pounds</option>
            <option value="stone">stone</option>
          </select>
        </div>
      </div>
      <div>
        <label>Desired Weight:</label>
        <div className="input-group">
          <input
            type="text"
            name="desiredWeight"
            value={formData.desiredWeight}
            onChange={handleChange}
            placeholder="Enter your desired weight"
          />
          <select
            name="weightUnit"
            value={formData.weightUnit}
            onChange={handleChange}
          >
            <option value="kg">kg</option>
            <option value="lbs">pounds</option>
            <option value="stone">stone</option>
          </select>
        </div>
      </div>
      <div>
        <label>Sex:</label>
        <select
          name="sex"
          value={formData.sex}
          onChange={handleChange}
        >
          <option value="">Select your sex</option>
          <option value="male">Male</option>
          <option value="female">Female</option>
          <option value="other">Other</option>
        </select>
      </div>
      <div>
        <label>Date of Birth:</label>
        <input
          type="date"
          name="dob"
          value={formData.dob}
          onChange={handleChange}
        />
      </div>
      <div className="button-group">
        <button type="button" onClick={handleBack}>Back</button>
        <button type="submit">Create Account</button>
      </div>
    </form>
  );
}

export default RegistrationStep2;
